########## include/common/log.h ##########
/* Structured logging. Every line is machine-parseable, because the 48-hour soak log
 * is a graded deliverable and we will have to plot it. (handout §3.4) */
#ifndef CARWATCH_LOG_H
#define CARWATCH_LOG_H

#include <stdint.h>

typedef enum { LOG_DEBUG, LOG_INFO, LOG_WARN, LOG_ERROR, LOG_FATAL } log_level_t;

/* Data provenance. CLAUDE.md §2.7: replayed or synthesized data is labeled as such
 * EVERYWHERE it appears. This field exists from day one so that it is impossible to
 * forget later. */
typedef enum { SRC_LIVE = 0, SRC_REPLAY = 1, SRC_SYNTH = 2 } data_src_t;

void        log_init(const char *component, log_level_t min);
void        log_set_src(data_src_t src);
data_src_t  log_get_src(void);
const char *log_src_name(data_src_t src);

void log_emit(log_level_t lvl, const char *fmt, ...)
    __attribute__((format(printf, 2, 3)));

/* Hourly heartbeat: process liveness, RSS, cumulative event counts. Required by the
 * soak (handout §3.4) and the source of the RSS-vs-time plot in EVALUATION.md §3. */
void log_heartbeat(uint64_t events, uint64_t drops);

#define LOG_D(...) log_emit(LOG_DEBUG, __VA_ARGS__)
#define LOG_I(...) log_emit(LOG_INFO,  __VA_ARGS__)
#define LOG_W(...) log_emit(LOG_WARN,  __VA_ARGS__)
#define LOG_E(...) log_emit(LOG_ERROR, __VA_ARGS__)

#endif
########## include/ipc/ring.h ##########
/* Single-producer / single-consumer lock-free ring — mechanism F.
 *
 * The no-drop guarantee is the point. A gap in the record is a gap in the diagnosis,
 * so a drop must be impossible to hide: every slot carries a sequence number and the
 * consumer accounts for every one of them. If the ring is full the producer must
 * report the overrun rather than silently overwrite an unread sample (D-002).
 *
 * Layout is fixed so the ring can live in shared memory across the process boundary
 * that mechanism E requires.
 */
#ifndef CARWATCH_RING_H
#define CARWATCH_RING_H

#include <stdatomic.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define RING_CAPACITY 4096u   /* power of two — the mask depends on it */
#define RING_PAYLOAD    16u   /* bytes; one CAN frame's data field fits with room */

typedef struct {
    uint64_t seq;                    /* monotonic, never reused */
    uint64_t mono_ns;                /* CLOCK_MONOTONIC at capture */
    uint32_t can_id;
    uint8_t  len;
    uint8_t  src;                    /* data_src_t — live | replay | synth */
    uint8_t  _pad[2];
    uint8_t  data[RING_PAYLOAD];
} ring_slot_t;

typedef struct {
    _Atomic uint64_t head;           /* producer writes */
    _Atomic uint64_t tail;           /* consumer writes */
    _Atomic uint64_t overruns;       /* refused pushes — must stay zero */
    uint64_t         _pad[5];        /* keep head/tail off one cache line */
    ring_slot_t      slot[RING_CAPACITY];
} ring_t;

void     ring_init(ring_t *r);

/* Returns false when full. Never overwrites an unread slot; increments overruns. */
bool     ring_push(ring_t *r, const ring_slot_t *in);

/* Returns false when empty. */
bool     ring_pop(ring_t *r, ring_slot_t *out);

uint64_t ring_overruns(const ring_t *r);
size_t   ring_depth(const ring_t *r);

#endif
########## include/store/record.h ##########
/* On-disk record format — mechanism D.
 *
 * The defining constraint: the power is cut mid-write every time the key turns off.
 * We never get a clean shutdown, so the format must let recovery find the torn tail
 * and truncate it without losing anything before it.
 *
 * Therefore every record is (a) self-framing, so a scan can resynchronize, and
 * (b) CRC'd over its whole body, so a partially-flushed record is detectable rather
 * than merely wrong.
 */
#ifndef CARWATCH_RECORD_H
#define CARWATCH_RECORD_H

#include <stdint.h>

#define REC_MAGIC   0x43574B31u   /* "CWK1" */
#define REC_VERSION 1u

typedef struct {
    uint32_t magic;      /* REC_MAGIC — resync anchor for the recovery scan */
    uint16_t version;
    uint16_t len;        /* bytes of payload following this header */
    uint64_t seq;        /* monotonic; a gap here is a detected loss, not a hidden one */
    uint64_t mono_ns;    /* CLOCK_MONOTONIC — for intervals, survives wall-clock jumps */
    uint64_t wall_ns;    /* CLOCK_REALTIME — may be wrong before NTP; see D-00x */
    uint8_t  src;        /* data_src_t — live | replay | synth. Never optional. */
    uint8_t  kind;       /* rec_kind_t */
    uint16_t _pad;
    uint32_t crc32;      /* over header-with-crc-zeroed, then payload */
} rec_hdr_t;

typedef enum {
    REC_CAN_FRAME  = 1,
    REC_SAMPLE     = 2,   /* decoded PID sample */
    REC_BASELINE   = 3,   /* persisted per-bin statistics — must survive power loss */
    REC_VERDICT    = 4,
    REC_FAULT      = 5,   /* detection / degradation / recovery event */
    REC_HEARTBEAT  = 6
} rec_kind_t;

uint32_t rec_crc32(const void *buf, uint32_t len);

#endif
########## src/common/log.c ##########
#include "common/log.h"

#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

static const char  *g_component = "?";
static log_level_t  g_min       = LOG_INFO;
static data_src_t   g_src       = SRC_LIVE;

static const char *level_name(log_level_t l)
{
    switch (l) {
    case LOG_DEBUG: return "DEBUG";
    case LOG_INFO:  return "INFO";
    case LOG_WARN:  return "WARN";
    case LOG_ERROR: return "ERROR";
    case LOG_FATAL: return "FATAL";
    }
    return "?";
}

void log_init(const char *component, log_level_t min)
{
    g_component = component;
    g_min       = min;
    setvbuf(stdout, NULL, _IOLBF, 0);
}

void log_set_src(data_src_t src) { g_src = src; }
data_src_t log_get_src(void)     { return g_src; }

const char *log_src_name(data_src_t src)
{
    switch (src) {
    case SRC_LIVE:   return "live";
    case SRC_REPLAY: return "replay";
    case SRC_SYNTH:  return "synth";
    }
    return "unknown";
}

static void stamp(char *buf, size_t n)
{
    struct timespec ts;
    struct tm       tm;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0 ||
        gmtime_r(&ts.tv_sec, &tm) == NULL) {
        snprintf(buf, n, "----------T--:--:--.---Z");
        return;
    }
    size_t k = strftime(buf, n, "%Y-%m-%dT%H:%M:%S", &tm);
    snprintf(buf + k, n - k, ".%03ldZ", ts.tv_nsec / 1000000L);
}

void log_emit(log_level_t lvl, const char *fmt, ...)
{
    if (lvl < g_min) return;

    char ts[40];
    stamp(ts, sizeof ts);

    /* ts level component src pid — then the message. Greppable and column-stable. */
    printf("%s %-5s %-10s src=%-6s pid=%d ",
           ts, level_name(lvl), g_component, log_src_name(g_src), (int)getpid());

    va_list ap;
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);

    putchar('\n');
}

/* Resident set size in KiB, from /proc/self/statm field 2 (pages). */
static long rss_kib(void)
{
    FILE *f = fopen("/proc/self/statm", "re");
    if (f == NULL) return -1;
    long total = 0, res = 0;
    int  got = fscanf(f, "%ld %ld", &total, &res);
    (void)fclose(f);
    if (got != 2) return -1;
    long page_kib = sysconf(_SC_PAGESIZE) / 1024;
    return res * page_kib;
}

void log_heartbeat(uint64_t events, uint64_t drops)
{
    log_emit(LOG_INFO, "heartbeat rss_kib=%ld events=%llu drops=%llu",
             rss_kib(), (unsigned long long)events, (unsigned long long)drops);
}
